var dep, pods = [];
function out(k, v) { document.getElementById('out').setAttribute('data-' + k, v); }
function said(k) { return function (r) { out(k, r && r.isError ? 'refused' : 'shown'); }; }
view.onData('deps', function (d) { dep = d.rows.filter(function (r) { return r.name === 'views-e2e'; })[0]; document.getElementById('dep').textContent = dep ? 'Deployment: ' + dep.name : 'no deployment'; });
view.onData('pods', function (d) { pods = d.rows; });
function on(id, fn) { document.getElementById(id).addEventListener('click', fn); }
on('restart', function () { view.action('restart', dep._ref).then(said('restart')); });
on('delete', function () { view.action('delete', dep._ref).then(said('delete')); });
on('drain', function () { view.action('drain', { kind: 'Node', name: 'orbstack' }).then(said('drain')); });
on('notshown', function () { view.action('restart', { kind: 'Deployment', namespace: 'landlens-dev', name: 'not-in-this-view' }).then(said('notshown')); });
on('ask', function () { view.ask(dep._ref).then(said('ask')); });
on('select', function () { view.select(pods.map(function (r) { return r._ref; })).then(said('select')); });
on('logs', function () { view.logs(dep._ref).then(said('logs')); });
